#include <iostream>
#include <string>
int main() {
    std::string s;
    std::cin >> s;
    int n = static_cast<int>(s.size());
    int current = 1, start = 0;
    int best = 1, bestStart = 0;
    for (int i = 1; i < n; ++i) {
        if (s[i] == s[i - 1]) {
            ++current;
        } else {
            current = 1;
            start = i;
        }
        if (current > best) {
            best = current;
            bestStart = start;
        }
    }
    std::cout << best << " " << bestStart + 1 << "\n";
    return 0;
}

