#include <iostream>
#include <queue>
#include <stack>
int main() {
    int n;
    std::cin >> n;
    std::queue<int> waiting;
    std::stack<int> done;
    for (int i = 0; i < n; ++i) {
        char op;
        std::cin >> op;
        if (op == 'A') {
            int x;
            std::cin >> x;
            waiting.push(x);
        } else if (op == 'S') {
            if (!waiting.empty()) {
                done.push(waiting.front());
                waiting.pop();
            }
        } else if (op == 'U') {
            if (!done.empty()) {
                waiting.push(done.top());
                done.pop();
            }
        }
    }
    int head = waiting.empty() ? 0 : waiting.front();
    int top = done.empty() ? 0 : done.top();
    std::cout << waiting.size() << " " << head << " "
              << done.size() << " " << top << "\n";
    return 0;
}

