void quickSort(std::vector<int>& a, int left, int right) {
    if (left >= right) return;
    int pivot = a[right];
    int k = left;
    for (int j = left; j < right; ++j) {
        if (a[j] <= pivot) {
            std::swap(a[k], a[j]);
            ++k;
        }
    }
    std::swap(a[k], a[right]);
    quickSort(a, left, k - 1);
    quickSort(a, k + 1, right);
}

